window.kbPageData["views/entry/k-61cf9b0cc6cc75cd"] = {"key":"entry/k-61cf9b0cc6cc75cd","state":{"route":"entry/k-61cf9b0cc6cc75cd"},"node":{"id":"k-61cf9b0cc6cc75cd","mode":"k","title":"加紧培育壮大新动能","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["industry","innovation"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（二）加紧培育壮大新动能。坚持把发展经济的着力点放在实体经济上，因地制宜发\n展新质生产力，建设现代化产业体系。\n优化提升传统产业①。持续推进重点产业提质升级，新部署一批重大技术改造升级项目，\n安排 2000 亿元超长期特别国债资金支持大规模设备更新。实施新一轮制造业重点产业链高\n质量发展行动，强化产…","sources":[{"id":"63c9502fca3ed409","label":"加紧培育壮大新动能","topic":"年度政府工作","category":"时政","text":"（二）加紧培育壮大新动能。坚持把发展经济的着力点放在实体经济上，因地制宜发\n展新质生产力，建设现代化产业体系。\n优化提升传统产业①。持续推进重点产业提质升级，新部署一批重大技术改造升级项目，\n安排 2000 亿元超长期特别国债资金支持大规模设备更新。实施新一轮制造业重点产业链高\n质量发展行动，强化产业基础再造和重大技术装备攻关，打造一批国家先进制造业集群。推\n行普惠性“上云用数赋智”服务，持续加大对中小企业数智化转型的支持。拓展智能制造，\n新建设一批智能工厂和智慧供应链。发展智能建造，培育现代化建筑产业链。加快推进标准\n升级，强化质量监督和品牌建设，支持企业提供更加优质、更具特色的产品。\n培育壮大新兴产业和未来产业②。实施产业创新工程，鼓励央企国企带头开放应用场景，\n打造集成电路、航空航天、生物医药、低空经济等新兴支柱产业。建立未来产业投入增长和\n风险分担机制，培育发展未来能源、量子科技、具身智能、脑机接口、6G 等未来产业。构\n建促进专精特新中小企业发展壮大机制，培育独角兽企业。高效用好国家创业投资引导基金，\n大力发展创业投资、天使投资，政府投资基金要带头做耐心资本，推动更多初创企业加快成\n长为科技领军企业。\n扩能提质服务业③。深化先进制造业和现代服务业融合发展试点。壮大科技服务市场，\n促进软件服务价值提升。发展金融、现代物流、知识产权、检验检测等生产性服务业。促进\n生活性服务业高品质、多样化、便利化发展。有序放宽服务业准入限制，扩大重点领域服务\n业投资。健全服务业国家标准，培育“中国服务”品牌。\n打造智能经济新形态④。深化拓展“人工智能+”，促进新一代智能终端和智能体加快推\n广，推动重点行业领域人工智能商业化规模化应用，培育智能原生新业态新模式。支持人工\n智能开源社区建设，促进开源生态繁荣。实施超大规模智算集群、算电协同等新基建工程，\n加强全国一体化算力监测调度，支持公共云发展。加快发展卫星互联网。打造“5G+工业互\n联网”升级版。深化数据资源开发利用，健全数据要素基础制度，建设高质量数据集。完善\n人工智能治理。","source":{"doc":"6cbfb01fe723bba64b75","first":25,"last":25,"page":25,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"},{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-61cf9b0cc6cc75cd":[]}};
